def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def phase(name: str, **payload: object) -> None:
    print(json.dumps({"phase": name, **payload}, ensure_ascii=False), flush=True)



def overlay_embedded_sources(repo: Path) -> None:
    """Overwrite cloned GitHub sources with the embedded dual-T4 OOM fix bundle."""
    payload = base64.b64decode(EMBEDDED_KRONOS_ARCHIVE_B64.strip())
    if not payload or EMBEDDED_KRONOS_ARCHIVE_B64.strip() == "PLACEHOLDER":
        raise SystemExit(
            "Embedded Kronos archive is empty; run "
            "finetune/build_kaggle_beta_v21_c1_dual_t4_kernel.py before push"
        )
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
        archive.extractall(repo.parent, filter="data")
    marker = repo / "finetune" / "train_predictor.py"
    if not marker.is_file():
        raise SystemExit(f"Embedded overlay missing {marker}")
    # Cheap sanity: scalar-only aux collection must be present.
    source = marker.read_text(encoding="utf-8", errors="replace")
    if "collect_validation_auxiliary" not in source:
        raise SystemExit("Embedded train_predictor.py missing aux-collection gate")
    if "pairwise_accuracy" not in source:
        raise SystemExit("Embedded train_predictor.py missing pairwise_accuracy")
    if "train_beta_v21_heads_only" not in source:
        raise SystemExit("Embedded train_predictor.py missing train_beta_v21_heads_only")
    if "bool(config.get('collect_validation_auxiliary', False))" not in source:
        raise SystemExit(
            "Embedded train_predictor.py still uses legacy CUDA aux all-gather"
        )
    phase(
        "source_overlay_ready",
        repo=str(repo),
        train_predictor_bytes=marker.stat().st_size,
        archive_bytes=len(payload),
    )


def clone_repo(repo: Path) -> str:
    phase("clone_started", repo=str(repo))
    shutil.rmtree(repo, ignore_errors=True)
    subprocess.run(
        [
            "git",
            "clone",
            "--depth",
            "3",
            "--branch",
            "master",
            "https://github.com/luckfu/Kronos.git",
            str(repo),
        ],
        check=True,
        env={**os.environ, "GIT_TERMINAL_PROMPT": "0"},
    )
    commit = subprocess.check_output(
        ["git", "rev-parse", "HEAD"], cwd=repo, text=True
    ).strip()
    phase("github_ready", commit=commit)
    return commit


def find_data_root(input_root: Path) -> Path:
    explicit = os.getenv("KRONOS_BETA_V1_1_DATA_ROOT", "").strip()
    if explicit:
        candidates = [Path(explicit).expanduser().resolve()]
    else:
        candidates = sorted(
            {
                path.parent.parent
                for path in input_root.glob("**/processed_datasets/train_data.pkl")
                if (path.parent / "val_data.pkl").is_file()
            }
        )
    if len(candidates) != 1:
        raise SystemExit(
            "Expected exactly one input data root with train_data.pkl and val_data.pkl; "
            f"found {len(candidates)}: {candidates}"
        )
    root = candidates[0]
    required = [
        root / "processed_datasets/train_data.pkl",
        root / "processed_datasets/val_data.pkl",
        root / "asset_metadata.csv",
        root / "data_manifest.json",
    ]
    missing = [str(path) for path in required if not path.is_file()]
    if missing:
        raise SystemExit(f"Data root is incomplete: {missing}")
    return root


def find_continuation(input_root: Path) -> Path | None:
    matches = sorted(
        input_root.glob(
            f"**/{OUTPUT_NAME}/checkpoints/last_state.pt"
        )
    )
    if not matches:
        return None
    if len(matches) != 1:
        raise SystemExit(f"Expected one continuation output, found {len(matches)}: {matches}")
    root = matches[0].parent.parent
    required = [
        "run.log",
        "metrics.jsonl",
        "progress.json",
        "summary.json",
        "experiment_manifest.json",
        "checkpoints/last_state.pt",
        "checkpoints/last_model/model.safetensors",
        "checkpoints/best_model/model.safetensors",
    ]
    missing = [name for name in required if not (root / name).is_file()]
    if missing:
        raise SystemExit(f"Continuation output is incomplete: {missing}")
    return root



def is_seg155_forecast_best(metric: dict) -> bool:
    """True only for chart Seg155 / local 26 forecast best (2.31236787)."""
    try:
        segment = int(metric.get("segment", -1))
        loss = float(metric.get(
            "selection_loss", metric.get("objective_loss", float("nan"))
        ))
    except (TypeError, ValueError):
        return False
    if str(metric.get("selection_metric") or "") != "forecast":
        return False
    return (
        segment in {EXPECTED_PARENT_CHART_SEGMENT, EXPECTED_PARENT_LOCAL_SEGMENT}
        and loss == loss
        and abs(loss - EXPECTED_PARENT_FORECAST_LOSS) <= 1e-8
    )


def find_seg155_forecast_best(input_root: Path) -> Path:
    """Point weights at Seg155 forecast best_model.

    Prefers the dedicated dataset mount (PARENT_DATASET). The user281434
    kernel output's wc/best_model is v16 Seg10 ranking and must be refused.
    """
    matches: list[Path] = []
    rejected: list[str] = []
    for metric_path in sorted(input_root.glob("**/best_metric.json")):
        best_dir = metric_path.parent
        # Accept either .../checkpoints/best_model/best_metric.json or a
        # root-level best_metric.json sitting next to checkpoints/.
        if best_dir.name == "best_model":
            candidate = best_dir
        elif (best_dir / "checkpoints" / "best_model" / "model.safetensors").is_file():
            candidate = best_dir / "checkpoints" / "best_model"
            metric_path = candidate / "best_metric.json"
            if not metric_path.is_file():
                continue
        else:
            continue
        if not (candidate / "model.safetensors").is_file():
            continue
        try:
            metric = json.loads(metric_path.read_text())
        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            continue
        if not is_seg155_forecast_best(metric):
            rejected.append(
                f"{candidate} metric={metric.get('selection_metric')} "
                f"segment={metric.get('segment')} "
                f"loss={metric.get('selection_loss')}"
            )
            continue
        matches.append(candidate.resolve())
    unique = list(dict.fromkeys(matches))
    if len(unique) != 1:
        raise SystemExit(
            "Refusing to auto-pick weights. Need exactly one chart Seg155 "
            f"forecast best_model (weighted_forecast_loss "
            f"{EXPECTED_PARENT_FORECAST_LOSS}, local segment "
            f"{EXPECTED_PARENT_LOCAL_SEGMENT}) under input. "
            f"Expected dataset {PARENT_DATASET}. "
            f"found={len(unique)} paths={unique}. rejected={rejected[:8]}."
        )
    return unique[0]


def ignore_optimizer_state(directory: str, names: list[str]) -> list[str]:
    """Keep last_state.pt out of the working copy so AdamW cannot resume it."""
    if Path(directory).name == "checkpoints" and "last_state.pt" in names:
        return ["last_state.pt"]
    return []


def download_model(runtime: Path) -> tuple[Path, Path]:
    target = runtime / "models" / "Kronos-A-Share-Beta-V1-1"
    phase("download_model_started", repo=MODEL_REPO, target=str(target))
    subprocess.run(
        [sys.executable, "-m", "pip", "install", "--disable-pip-version-check",
         "--progress-bar", "off", "modelscope>=1.20"],
        check=True,
    )
    from modelscope.hub.snapshot_download import snapshot_download

    target.mkdir(parents=True, exist_ok=True)
    snapshot_download(MODEL_REPO, local_dir=str(target))
    predictor = target / "best_model"
    tokenizer = target / "tokenizer"
    if not (predictor / "model.safetensors").is_file():
        predictor = target
    if not (tokenizer / "config.json").is_file():
        tokenizer = target / "tokenizer"
    required = [
        predictor / "config.json",
        predictor / "model.safetensors",
        tokenizer / "config.json",
        tokenizer / "model.safetensors",
    ]
    missing = [str(path) for path in required if not path.is_file()]
    if missing:
        raise SystemExit(f"ModelScope snapshot is incomplete: {missing}")
    actual_sha = sha256_file(predictor / "model.safetensors")
    if actual_sha != EXPECTED_BEST_SHA256:
        raise SystemExit(
            f"Beta v2.1 pretrained SHA mismatch: {actual_sha} != {EXPECTED_BEST_SHA256}"
        )
    tokenizer_sha = sha256_file(tokenizer / "model.safetensors")
    if tokenizer_sha != EXPECTED_TOKENIZER_SHA256:
        raise SystemExit(
            f"Tokenizer SHA mismatch: {tokenizer_sha} != {EXPECTED_TOKENIZER_SHA256}"
        )
    phase(
        "model_ready",
        checkpoint="pretrained_release",
        predictor=str(predictor),
        tokenizer=str(tokenizer),
        model_sha256=actual_sha,
        tokenizer_sha256=tokenizer_sha,
    )
    return predictor, tokenizer


